const char *nativeSilverGumbelStopModelId() { return kModelId; }
double nativeSilverGumbelStopModelDefaultThreshold() { return kDefaultThreshold; }
double nativeSilverGumbelStopModelRisk(const NativeSilverGumbelStopFeatures &x) {
    double s = kBaseline;
    for (int t = 0; t < kTreeCount; ++t) {
        int i = 0;
        const Node *base = kNodes + kTreeStart[t];
        while (!base[i].leaf) i = x[base[i].feature] <= base[i].threshold ? base[i].left : base[i].right;
        s += base[i].value;
    }
    return 1.0 / (1.0 + std::exp(-s));
}

